import{_ as s,o as a,c as t,ag as i}from"./chunks/framework.jVX1Yi1C.js";const k=JSON.parse('{"title":"Setup on macOS","description":"","frontmatter":{},"headers":[],"relativePath":"setup-macos.md","filePath":"setup-macos.md"}'),h={name:"setup-macos.md"};function n(o,e,l,p,d,r){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="setup-on-macos" tabindex="-1">Setup on macOS <a class="header-anchor" href="#setup-on-macos" aria-label="Permalink to &quot;Setup on macOS&quot;">​</a></h1><p>This page gives each step from a clean Mac to a working harness. <a href="https://github.com/michakraus/ResearchHarness#installation" target="_blank" rel="noreferrer">Installation</a> gives the short form of the same steps. <a href="./setup-linux">setup-linux.md</a> is the page for Linux.</p><p>The steps use <code>~/Research/Harness</code> as the path of the checkout. The profile key <code>harness</code> holds the absolute path of the checkout, for example <code>/Users/me/Research/Harness</code>.</p><h2 id="the-dependencies" tabindex="-1">The dependencies <a class="header-anchor" href="#the-dependencies" aria-label="Permalink to &quot;The dependencies&quot;">​</a></h2><p><a href="./dependencies">Dependencies</a> lists each tool, its minimum version and what the harness uses it for. Its section <a href="./dependencies#what-each-tool-does">What each tool does</a> says what each tool does, why the harness needs it, and where the harness calls it.</p><p>Homebrew supplies most of the required tools on macOS. These commands install them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python@3.11</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gitleaks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shellcheck</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> actionlint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coreutils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> juliaup</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jolars/tap/fatou</span></span></code></pre></div><p><code>harness</code> runs on the <code>python3</code> of the <code>PATH</code>, which must be 3.11 or later. <code>python</code> supplies a current <code>python3</code>, and <code>python@3.11</code> supplies <code>python3.11</code>, which the pre-push hook also runs. <code>coreutils</code> supplies <code>timeout</code>, which macOS does not have. Then install Julia 1.13 or later with <code>juliaup</code>. The optional tools serve one frontend or one job each. Install them when you need that frontend or that job.</p><h2 id="the-clone" tabindex="-1">The clone <a class="header-anchor" href="#the-clone" aria-label="Permalink to &quot;The clone&quot;">​</a></h2><p>Clone the repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/michakraus/ResearchHarness.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Harness</span></span></code></pre></div><p>Put its <code>bin/</code> directory on the <code>PATH</code>. Add the same line to your shell&#39;s start file, for example <code>~/.zshrc</code>, so that each new shell finds <code>harness</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Research/Harness/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p><code>harness --help</code> must now list the verbs. A Python older than 3.11 makes <code>harness</code> stop with exit 2 and the version that it found.</p><h2 id="the-profile-and-the-model-tables" tabindex="-1">The profile and the model tables <a class="header-anchor" href="#the-profile-and-the-model-tables" aria-label="Permalink to &quot;The profile and the model tables&quot;">​</a></h2><p>The profile holds every value that names a person, an institution or a machine. The model tables hold the model of each tier for each frontend. The repository holds an example of each in <code>examples/</code>. Copy the two examples, then write your values into them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/research-harness</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Harness/examples/profile.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/research-harness/profile.toml</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Harness/examples/models.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/research-harness/models.toml</span></span></code></pre></div><p>In the profile, replace the example path <code>/home/example</code> with your home directory, for example <code>/Users/me</code>, in each value. The key <code>harness</code> then holds the absolute path of the checkout. Each entry of <code>repository_roots</code> must be a directory, else <code>harness leaks</code> stops with exit 2. <a href="./profile">profile.md</a> names each key and table, and the verbs that read it. The comments in the two examples say what each value is.</p><h2 id="the-tree-instructions" tabindex="-1">The tree instructions <a class="header-anchor" href="#the-tree-instructions" aria-label="Permalink to &quot;The tree instructions&quot;">​</a></h2><p>The tree instructions are a directory of private instruction text about your own research tree. <code>harness install</code> installs them into <code>~/.claude/</code> beside the sources of this repository. The profile key <code>tree_agents</code> gives the absolute path of the directory. The directory must exist, else <code>harness install</code> stops with exit 2.</p><p>The directory has the layout of <code>~/.claude/</code>. <code>adapters/claude/CLAUDE.md</code> imports <code>instructions/research-tree.md</code>, so put the facts about your tree into that file. A minimal directory holds that one file. With the example value of <code>tree_agents</code>, these commands make it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Environment/Agents/instructions</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Environment/Agents/instructions/research-tree.md</span></span></code></pre></div><p><a href="./architecture#the-three-layers">architecture.md</a> says how the tree instructions relate to the harness and the profile.</p><h2 id="harness-install-apply" tabindex="-1"><code>harness install --apply</code> <a class="header-anchor" href="#harness-install-apply" aria-label="Permalink to &quot;`harness install --apply`&quot;">​</a></h2><p><code>harness install</code> needs two directories: <code>~/.claude/skills/</code> and the OpenCode configuration directory, <code>$OPENCODE_CONFIG_DIR</code>, else <code>~/.config/opencode/</code>. On a new machine, make them before the first install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/opencode</span></span></code></pre></div><p>Without the OpenCode directory, <code>harness install</code> stops with exit 2 and tells you to start OpenCode once. Without <code>~/.claude/skills/</code>, it stops with exit 2 and says that the path is not a directory.</p><p>Then run the dry run. It prints each file that it would install and exits 1:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Read the plan, then make the change:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p>The first <code>--apply</code> also instantiates the Julia environment of the scripts, so it downloads the Julia packages of <code>Project.toml</code>. The warnings after the plan name what the install does not do for you. For example, the Kaimon entry needs a token file, and <code>harness install</code> does not write <code>~/.claude/settings.json</code>.</p><h3 id="opencode" tabindex="-1">OpenCode <a class="header-anchor" href="#opencode" aria-label="Permalink to &quot;OpenCode&quot;">​</a></h3><p><code>harness install</code> writes the OpenCode configuration into the OpenCode configuration directory: <code>opencode.jsonc</code> with its permission block, the plugins, the global instruction file <code>AGENTS.md</code> and the agents. It also links the skills into <code>~/.agents/skills/</code>. <a href="./architecture#the-opencode-and-oh-my-pi-adapters">architecture.md</a> describes the adapter.</p><h3 id="oh-my-pi" tabindex="-1">oh-my-pi <a class="header-anchor" href="#oh-my-pi" aria-label="Permalink to &quot;oh-my-pi&quot;">​</a></h3><p><code>harness install</code> writes the oh-my-pi configuration into its agent directory, <code>$PI_CODING_AGENT_DIR</code>, else <code>~/.omp/agent/</code>: <code>config.yml</code> with the permission layer and the models, the guard extension, <code>AGENTS.md</code>, the rules, the agents and <code>mcp.json</code>. <a href="./architecture#the-opencode-and-oh-my-pi-adapters">architecture.md</a> describes the adapter.</p><h2 id="harness-settings-install-apply" tabindex="-1"><code>harness settings install --apply</code> <a class="header-anchor" href="#harness-settings-install-apply" aria-label="Permalink to &quot;`harness settings install --apply`&quot;">​</a></h2><p><code>harness settings install</code> writes the sections <code>permissions</code>, <code>hooks</code> and <code>sandbox</code> of <code>~/.claude/settings.json</code> from the settings template. It keeps every other key of the file. The file must exist, else the verb stops with exit 2. If it does not exist, make an empty one:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/settings.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/settings.json</span></span></code></pre></div><p>Run the dry run. It prints the difference and exits 1:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Then install the sections:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p>The installed settings refuse an edit of <code>~/.claude/settings.json</code> from a session. So you run this verb yourself, in your own terminal. <a href="./security">security.md</a> describes what the settings stop, and how to check a change of them.</p><h2 id="git-config-core-hookspath-githooks" tabindex="-1"><code>git config core.hooksPath .githooks</code> <a class="header-anchor" href="#git-config-core-hookspath-githooks" aria-label="Permalink to &quot;`git config core.hooksPath .githooks`&quot;">​</a></h2><p>The pre-push hook of this repository runs the leak checks and the tests before a push to <code>main</code>. Enable it once in the checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Harness</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.hooksPath</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .githooks</span></span></code></pre></div><p><a href="./development#the-pre-push-hook">development.md</a> describes the hook. Do this step when you change the harness and push. A user who only installs the harness can skip it.</p><h2 id="the-check-that-it-worked" tabindex="-1">The check that it worked <a class="header-anchor" href="#the-check-that-it-worked" aria-label="Permalink to &quot;The check that it worked&quot;">​</a></h2><p>Run the dry run of the install again. It must report <code>0 change(s) to make.</code> and exit 0:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>The dry run of the settings must exit 0 too:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Then run the harness&#39;s own test cases. The last line gives the number of cases, and it must say <code>0 wrong</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>At the start of each new Claude Code session, the <code>SessionStart</code> hook compares <code>~/.claude/</code> with the sources. A session that starts with no warning has the installed layer of the sources.</p>',56)])])}const g=s(h,[["render",n]]);export{k as __pageData,g as default};
